; ugtest.asm -- UGTEST.EXE: the M stand test program (MAME, DSS).
;
; Loads one UNET-GAME DLL with the embedded libman (L1 into WIN1), plays
; the gateway (ISA lock byte, #1FFD / #9FBD shadows, context, slots, event
; queue and UART ring in WIN2), keeps now_ms from the CTC2/CTC3 chain (the
; Worms set-up: /112 -> /156, polled, no interrupt), runs one scenario and
; leaves a text report in memory (UG_REPORT) for tools/mame/ugstand.lua.
;
; Build: tools/mame/run_esp.py (sjasmplus, -D SCEN=<char>, the include
; generated by tools/mame/mkcfg.js: memory map + INIT_CONFIG block).
; Scenarios: 'E' echo 300 bytes, 'S' 8 KiB stream, 'P' the peer closes
; (TCP), 'D' SHUTDOWN with the channel open.
;
; This is application code: it may call DSS and wait.  ESP builds: before
; the DLL is loaded the program plays NETUP once (AT, AT+UART_CUR with
; RTS/CTS), as the ТЗ leaves the module set-up to the system tools.

	DEVICE	NOSLOT64K

	INCLUDE	"UNETGAME.INC"
	INCLUDE	"unetg_ctx.inc"		; ctx.out_hl, ctx.hw_state (this repository's own tool)
	INCLUDE	"ugcfg.inc"

	DEFINE	LIBMAN_MAX_LIBS 1
	DEFINE	LIBMAN_NO_LEGACY_API
	DEFINE	LIBMAN_L0_L1_ONLY

EXE_HEADER_SIZE	EQU	0x200
EXE_LOAD	EQU	0x8100
STACK_TOP	EQU	UG_MSTK + UG_MSTK_LEN
DSS		EQU	0x10
DSS_EXIT	EQU	0x41
DSS_PCHARS	EQU	0x5C
P_SYS		EQU	0x3C		; SYS port, user mode
P_CTC2		EQU	0x12
P_CTC3		EQU	0x13
CTC_CHAIN	EQU	0x57		; counter mode, constant follows, reset, no interrupt
STEP_BUDGET	EQU	500
UHW_RUN		EQU	2
SH_1FFD		EQU	0x01		; DSS value: RAM in WIN0, ISA closed
SH_9FBD		EQU	0x00
UART		EQU	0xC3E8		; io_base 0x3E8 in the ISA window
RP_STATUS	EQU	8		; report: "UGTREP1",0, status ('R' running, 'P', 'F'), reason
RP_TEXT		EQU	16

	ORG	EXE_LOAD - EXE_HEADER_SIZE
exe_header
	DB	"EXE", 1
	DD	EXE_HEADER_SIZE
	DW	0
	DS	6, 0
	DW	start
	DW	start
	DW	STACK_TOP
	DB	0
	DS	EXE_HEADER_SIZE - ($ - exe_header), 0
	ASSERT	$ == EXE_LOAD

start
	LD	SP,STACK_TOP
	; turbo on (21 MHz, the v1 profile): SYS port, user mode, bit 1 = write
	; the turbo latch, bit 0 = its value (Worms ports.inc, P_SYS_OFF)
	LD	A,0x03
	OUT	(P_SYS),A
	CALL	rep_init
	LD	HL,s_title
	CALL	rp_str
	LD	HL,dll_name
	CALL	rp_str
	CALL	rp_nl
	CALL	tick_install
	CALL	ctc_init
	CALL	calibrate
	LD	HL,s_cal
	CALL	rp_str
	LD	HL,(cal_ctc)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(cal_loop)
	CALL	rp_hex16
	CALL	rp_nl
	; counts of STEP_BUDGET us: a frame is ~20.5 ms, 500 us ~ 1/41 of it
	LD	HL,(cal_ctc)
	LD	DE,41
	LD	BC,0
.lim
	OR	A
	SBC	HL,DE
	JR	C,.lim_ok
	INC	BC
	JR	.lim
.lim_ok
	LD	(st_lim),BC
	; gateway state
	LD	HL,UG_GW
	LD	(HL),0			; ISA lock free
	INC	HL
	LD	(HL),SH_1FFD
	INC	HL
	LD	(HL),SH_9FBD
	IF	UG_ESP
	CALL	netup
	ENDIF
	; load the DLL into WIN1 (libman calls INIT)
	LD	HL,dll_name
	LD	A,1
	CALL	LIBMAN.l_load
	JR	NC,.loaded
	LD	A,(LIBMAN.l_reason)	; why libman refused
	CALL	rp_hex8
	CALL	rp_nl
	LD	A,'L'
	JP	fail
.loaded
	LD	(dll_handle),HL
	LD	A,1
	LD	(dll_loaded),A
	; the application zeroes the context before the first INIT_CONFIG
	LD	HL,UG_CTX
	LD	DE,UG_CTX + 1
	LD	BC,UG_CTX_LEN - 1
	LD	(HL),0
	LDIR
	LD	IX,ginfo
	LD	DE,64
	LD	B,UNETG_GET_INFO
	CALL	dll
	LD	HL,s_info
	LD	DE,ginfo
	LD	B,64
	CALL	rp_dump
	LD	IX,cfg_block
	LD	B,UNETG_INIT_CONFIG
	CALL	dll
	PUSH	AF
	LD	HL,s_cfg
	CALL	rp_str
	POP	AF
	PUSH	AF
	CALL	rp_hex8
	CALL	rp_nl
	POP	AF
	OR	A
	LD	A,'C'
	JP	NZ,fail
	; bring-up (ESP: UART + AT set-up), at most 10 s
	LD	HL,10000
	CALL	dl_set
.hw
	CALL	pump
	LD	A,(UG_CTX + UCTX_HW_STATE)
	CP	UHW_RUN
	JR	Z,.hw_ok
	CALL	dl_due
	JR	NC,.hw
	LD	A,'H'
	JP	fail
.hw_ok
	LD	HL,s_hw
	CALL	rp_str
	CALL	scenario
	CALL	stats			; while the context is configured
	; SHUTDOWN until OK (3 s)
	LD	HL,s_shut
	CALL	rp_str
	LD	HL,3000
	CALL	dl_set
.shut
	LD	B,UNETG_SHUTDOWN
	CALL	dll
	OR	A
	JR	Z,.shut_ok
	CP	UNETG_STATUS_WORK
	JR	NZ,.shut_bad
	CALL	pump
	CALL	dl_due
	JR	NC,.shut
.shut_bad
	CALL	rp_hex8
	LD	A,'X'
	JP	fail
.shut_ok
	CALL	rp_nl
	LD	A,(fail_code)
	OR	A
	JP	NZ,fail
	LD	A,'P'
	JR	finish

; fail: A = reason code (letter)
fail
	LD	(fail_code),A
	LD	A,(dll_loaded)		; DLL loaded: statistics first
	OR	A
	JR	Z,.no_dll
	PUSH	AF
	CALL	stats
	POP	AF
.no_dll
	LD	A,'F'
finish
	LD	(UG_REPORT + RP_STATUS),A
	LD	A,(fail_code)
	LD	(UG_REPORT + RP_STATUS + 1),A
	CALL	rp_result
	; FINI and release
	LD	A,(dll_loaded)
	OR	A
	JR	Z,.freed
	XOR	A
	LD	(dll_loaded),A
	LD	HL,(dll_handle)
	CALL	LIBMAN.l_free
.freed
	CALL	ctc_stop
	CALL	tick_remove
	LD	HL,UG_REPORT + RP_TEXT
	LD	C,DSS_PCHARS
	RST	DSS
	LD	A,0xA5
	LD	(UG_REPORT + RP_STATUS + 2),A	; done: ugstand.lua collects the report
.spin
	JR	.spin

rp_result
	LD	HL,s_result
	CALL	rp_str
	LD	A,(UG_REPORT + RP_STATUS)
	CP	'P'
	LD	HL,s_pass
	JR	Z,.r
	LD	HL,s_failr
	CALL	rp_str
	LD	A,(fail_code)
	CALL	rp_char
	LD	HL,s_crlf
.r
	JP	rp_str

; ----------------------------------------------------------------------
; Scenarios
; ----------------------------------------------------------------------
scenario
	CALL	open_wait
	IF	SCEN == 'E'
	LD	HL,300
	LD	(tx_total),HL
	CALL	send_all
	CALL	close_wait
	ENDIF
	IF	SCEN == 'S'
	LD	HL,8192
	LD	(tx_total),HL
	CALL	send_all
	CALL	close_wait
	ENDIF
	IF	SCEN == 'P'
	; the echo server closes after 64 bytes: PEER_CLOSED, then CLOSED
	LD	HL,64
	LD	(tx_total),HL
	CALL	send_all
	LD	HL,5000
	CALL	dl_set
.pc
	CALL	pump
	LD	A,(ev_closed)
	OR	A
	JR	NZ,.pc_done
	CALL	dl_due
	JR	NC,.pc
	LD	A,'p'
	JP	fail
.pc_done
	LD	A,(ev_peer)
	OR	A
	RET	NZ
	LD	A,'q'
	LD	(fail_code),A
	ENDIF
	IF	SCEN == 'D'
	LD	HL,100
	LD	(tx_total),HL
	CALL	send_one
	LD	HL,200
	CALL	dl_set
.d
	CALL	pump
	CALL	dl_due
	JR	NC,.d
	ENDIF
	RET

; open_wait: OPEN, CONNECTED within 15 s
open_wait
	LD	HL,s_open
	CALL	rp_str
	LD	IX,0
	LD	B,UNETG_OPEN
	CALL	dll
	OR	A
	LD	A,'O'
	JP	NZ,fail
	LD	HL,15000
	CALL	dl_set
.w
	CALL	pump
	LD	A,(ev_connected)
	OR	A
	RET	NZ
	LD	A,(ev_closed)
	OR	A
	LD	A,'R'
	JP	NZ,fail
	CALL	dl_due
	JR	NC,.w
	LD	A,'T'
	JP	fail

; send_all: tx_total bytes in slot-size pieces, the echo checked, 30 s
send_all
	LD	HL,30000
	CALL	dl_set
.loop
	CALL	send_one
	CALL	pump
	LD	HL,(rx_count)
	LD	DE,(tx_total)
	OR	A
	SBC	HL,DE
	JR	NC,.done
	CALL	dl_due
	JR	NC,.loop
	LD	A,'E'
	JP	fail
.done
	LD	A,(rx_bad)
	OR	A
	LD	A,'B'
	JP	NZ,fail
	LD	HL,s_echo
	CALL	rp_str
	LD	HL,(rx_count)
	CALL	rp_hex16
	JP	rp_nl

; send_one: one TX slot of the pattern when there is room
send_one
	LD	HL,(tx_total)
	LD	DE,(tx_sent)
	OR	A
	SBC	HL,DE
	RET	Z
	LD	DE,UG_SLOT
	CALL	min_de_hl		; DE = this piece
	PUSH	DE
	LD	B,UNETG_TX_RESERVE
	CALL	dll
	POP	BC			; BC = piece
	OR	A
	RET	NZ			; no free slot yet
	LD	A,E
	LD	(tx_slot),A
	LD	HL,(UG_CTX + UCTX_OUT_HL)
	PUSH	BC
	LD	A,(tx_gen)
.fill
	LD	(HL),A
	ADD	A,31
	INC	HL
	DEC	BC
	LD	E,A
	LD	A,B
	OR	C
	LD	A,E
	JR	NZ,.fill
	LD	(tx_gen),A
	POP	DE			; length
	PUSH	DE
	LD	A,(tx_slot)
	LD	IX,(tx_tag)
	LD	B,UNETG_TX_COMMIT
	CALL	dll
	POP	DE
	OR	A
	LD	A,'K'
	JP	NZ,fail
	LD	HL,(tx_sent)
	ADD	HL,DE
	LD	(tx_sent),HL
	LD	HL,(tx_tag)
	INC	HL
	LD	(tx_tag),HL
	RET

; close_wait: CLOSE, CLOSED within 5 s
close_wait
	LD	B,UNETG_CLOSE
	CALL	dll
	OR	A
	LD	A,'c'
	JP	NZ,fail
	LD	HL,5000
	CALL	dl_set
.w
	CALL	pump
	LD	A,(ev_closed)
	OR	A
	RET	NZ
	CALL	dl_due
	JR	NC,.w
	LD	A,'d'
	JP	fail

; ----------------------------------------------------------------------
; pump: one STEP, its events and the RX data (pattern checked)
; ----------------------------------------------------------------------
pump
	CALL	clk_update
	CALL	ctc_phase
	LD	(st_t0),HL
	LD	IX,(now_ms)
	LD	IY,(now_ms + 2)
	LD	DE,STEP_BUDGET
	XOR	A
	LD	B,UNETG_STEP
	CALL	dll
	CALL	ctc_phase
	LD	DE,(st_t0)
	OR	A
	SBC	HL,DE			; modulo the 65536-count CTC3 period
	; STEP time statistics (CTC counts, 875 kHz): n, sum, > 500 us, max
	PUSH	HL
	LD	DE,(st_n)
	INC	DE
	LD	(st_n),DE
	LD	DE,(st_sum)
	ADD	HL,DE
	LD	(st_sum),HL
	JR	NC,.sum_ok
	LD	HL,(st_sum + 2)
	INC	HL
	LD	(st_sum + 2),HL
.sum_ok
	POP	HL
	PUSH	HL
	LD	DE,(st_lim)		; counts of STEP_BUDGET us (from the calibration)
	OR	A
	SBC	HL,DE
	JR	C,.in_budget
	LD	HL,(st_over)
	INC	HL
	LD	(st_over),HL
.in_budget
	POP	HL
	LD	DE,(st_max)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	JR	C,.events
	LD	(st_max),HL
.events
	LD	B,8
.ev
	PUSH	BC
	LD	IX,evbuf
	LD	B,UNETG_NEXT_EVENT
	CALL	dll
	POP	BC
	OR	A
	JR	NZ,.rx
	CALL	event
	DJNZ	.ev
.rx
	LD	B,4
.peek
	PUSH	BC
	LD	B,UNETG_RX_PEEK
	CALL	dll
	OR	A
	JR	NZ,.rx_end
	; DE = length, data at ctx.out_hl
	LD	HL,(UG_CTX + UCTX_OUT_HL)
	LD	A,(rx_gen)
	LD	C,A
.cmp
	LD	A,D
	OR	E
	JR	Z,.cmp_end
	LD	A,(HL)
	CP	C
	JR	Z,.same
	LD	A,1
	LD	(rx_bad),A
.same
	LD	A,C
	ADD	A,31
	LD	C,A
	INC	HL
	DEC	DE
	PUSH	HL
	LD	HL,(rx_count)
	INC	HL
	LD	(rx_count),HL
	POP	HL
	JR	.cmp
.cmp_end
	LD	A,C
	LD	(rx_gen),A
	LD	B,UNETG_RX_RELEASE
	CALL	dll
	POP	BC
	DJNZ	.peek
	RET
.rx_end
	POP	BC
	RET

; event: evbuf holds one event; flags + a report entry "tt/ss "
event
	LD	A,(evbuf + UNETG_EVT_TYPE)
	CP	UNETG_EV_CONNECTED
	JR	NZ,.e1
	LD	(ev_connected),A
.e1
	CP	UNETG_EV_CLOSED
	JR	NZ,.e2
	LD	(ev_closed),A
.e2
	CP	UNETG_EV_PEER_CLOSED
	JR	NZ,.e3
	LD	(ev_peer),A
.e3
	CP	UNETG_EV_RX_READY
	RET	Z			; not logged (frequent)
	CP	UNETG_EV_TX_DONE
	JR	NZ,.log
	LD	A,(evbuf + UNETG_EVT_STATUS)
	OR	A
	RET	Z			; TX_DONE OK: not logged
	LD	A,'t'
	LD	(fail_code),A
	LD	A,(evbuf + UNETG_EVT_TYPE)
.log
	PUSH	AF
	LD	HL,s_ev
	CALL	rp_str
	POP	AF
	CALL	rp_hex8
	LD	A,'/'
	CALL	rp_char
	LD	A,(evbuf + UNETG_EVT_DETAIL)
	CALL	rp_hex8
	JP	rp_nl

; stats: GET_STATS dump, STEP times and the cost of a trivial export call
; (RX_PEEK with nothing to read: libman + dispatch), all in CTC counts
stats
	CALL	ctc_phase
	LD	(st_t0),HL
	LD	B,16
.call
	PUSH	BC
	LD	B,UNETG_RX_PEEK
	CALL	dll
	POP	BC
	DJNZ	.call
	CALL	ctc_phase
	LD	DE,(st_t0)
	OR	A
	SBC	HL,DE
	PUSH	HL
	LD	HL,s_calltime
	CALL	rp_str
	POP	HL
	CALL	rp_hex16
	CALL	rp_nl
	LD	IX,gstats
	LD	DE,80
	LD	B,UNETG_GET_STATS
	CALL	dll
	LD	HL,s_stats
	LD	DE,gstats
	LD	B,80
	CALL	rp_dump
	LD	HL,s_maxstep
	CALL	rp_str
	LD	HL,(st_max)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(st_n)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(st_sum + 2)
	CALL	rp_hex16
	LD	HL,(st_sum)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(st_over)
	CALL	rp_hex16
	CALL	rp_nl
	LD	HL,s_now
	CALL	rp_str
	CALL	clk_update
	LD	HL,(now_ms + 2)
	CALL	rp_hex16
	LD	HL,(now_ms)
	CALL	rp_hex16
	JP	rp_nl

; dll: call export B with A, DE, IX, IY; returns A, DE.  libman refusal
; (CF) is fatal.
dll
	PUSH	AF
	LD	HL,(dll_handle)
	POP	AF
	CALL	LIBMAN.l_call
	RET	NC
	LD	A,'M'
	LD	(fail_code),A
	LD	A,'F'
	JP	finish

min_de_hl				; DE = min(DE, HL)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	RET	NC
	EX	DE,HL
	RET

; ----------------------------------------------------------------------
; Time.  now_ms = frame ticks x 20: an IM1 hook counts the 50 Hz frame
; interrupts (DSS lets a program replace the JP target at #0039).
; Durations: CTC2 in timer mode (prescaler 16, /256) -> CTC3 counting its
; zero counts (/256): a phase in units of 16 CTC clocks, calibrated against
; the frame tick at start (cal_ctc = counts per frame, cal_loop = loops of
; a 35-T loop per frame: the CPU speed).
; ----------------------------------------------------------------------
IM1_VECTOR	EQU	0x0039
tick_install
	DI
	LD	HL,(IM1_VECTOR)
	LD	(im1_old),HL
	LD	HL,im1_tick
	LD	(IM1_VECTOR),HL
	EI
	RET
tick_remove
	DI
	LD	HL,(im1_old)
	LD	(IM1_VECTOR),HL
	EI
	RET
im1_tick
	PUSH	HL
	LD	HL,(ticks)
	INC	HL
	LD	(ticks),HL
	POP	HL
	DB	0xC3			; JP to the DSS handler
im1_old	DW	0

ctc_init
	DI
	LD	A,0x07			; timer, prescaler 16, constant follows, reset
	OUT	(P_CTC2),A
	XOR	A			; 256
	OUT	(P_CTC2),A
	LD	A,CTC_CHAIN		; counter of CTC2 zero counts
	OUT	(P_CTC3),A
	XOR	A
	OUT	(P_CTC3),A
	EI
	RET
ctc_stop
	LD	A,0x03			; channel reset
	OUT	(P_CTC2),A
	OUT	(P_CTC3),A
	RET

; ctc_phase: HL = elapsed counts (16 CTC clocks) in the CTC3 period
; (CTC3, CTC2, CTC3 again, as Worms ctcnow.inc).  Clobbers A, BC.
ctc_phase
.retry
	IN	A,(P_CTC3)
	LD	B,A
	IN	A,(P_CTC2)
	LD	C,A
	IN	A,(P_CTC3)
	CP	B
	JR	NZ,.retry
	XOR	A
	SUB	B
	LD	H,A
	XOR	A
	SUB	C
	LD	L,A
	RET

wait_tick
	LD	A,(ticks)
	LD	B,A
.w
	LD	A,(ticks)
	CP	B
	JR	Z,.w
	RET

calibrate
	CALL	wait_tick
	CALL	ctc_phase
	LD	(cal_p0),HL
	CALL	wait_tick
	CALL	ctc_phase
	LD	DE,(cal_p0)
	OR	A
	SBC	HL,DE
	LD	(cal_ctc),HL
	CALL	wait_tick
	LD	DE,0
	LD	HL,(ticks)
.loop
	INC	DE			; 6 + 13 + 4 + 12 = 35 T
	LD	A,(ticks)
	CP	L
	JR	Z,.loop
	LD	(cal_loop),DE
	RET

; clk_update: now_ms = ticks x 20.  Clobbers A, BC, DE, HL.
clk_update
	LD	HL,(ticks)		; one instruction: no torn read
	XOR	A
	ADD	HL,HL
	ADC	A,A			; x2
	ADD	HL,HL
	ADC	A,A			; x4
	PUSH	AF
	PUSH	HL
	ADD	HL,HL
	ADC	A,A			; x8
	ADD	HL,HL
	ADC	A,A			; x16
	POP	DE
	POP	BC			; B = high byte of x4
	ADD	HL,DE
	ADC	A,B			; x20
	LD	(now_ms),HL
	LD	(now_ms + 2),A
	XOR	A
	LD	(now_ms + 3),A
	RET

; dl_set: deadline = now + HL ms (16-bit horizon is enough here)
dl_set
	PUSH	HL
	CALL	clk_update
	POP	HL
	LD	DE,(now_ms)
	ADD	HL,DE
	LD	(deadline),HL
	RET
; dl_due: CF=1 when the deadline is reached
dl_due
	CALL	clk_update
	LD	HL,(deadline)
	LD	DE,(now_ms)
	OR	A
	SBC	HL,DE
	BIT	7,H
	SCF
	RET	NZ			; past
	LD	A,H
	OR	L
	SCF
	RET	Z
	OR	A
	RET

; ----------------------------------------------------------------------
; NETUP role (ESP): module UART at 115200 8N1 with RTS/CTS, as
; sprinter_wifi/network NETUP does (AT+UART_CUR=...,3).
; ----------------------------------------------------------------------
	IF	UG_ESP
netup
	CALL	isa_open
	LD	HL,UART + 1
	LD	(HL),0			; IER
	LD	HL,UART + 3
	LD	(HL),0x83		; DLAB
	LD	HL,UART
	LD	(HL),8			; 115200 at 14.7456 MHz
	INC	HL
	LD	(HL),0
	LD	HL,UART + 3
	LD	(HL),0x03		; 8N1
	LD	HL,UART + 2
	LD	(HL),0x87		; FIFO, resets, trigger 8
	LD	HL,UART + 4
	LD	(HL),0x22		; AFE + RTS
	CALL	isa_close
	LD	HL,s_at
	CALL	at_cmd
	LD	HL,s_uartcur
	CALL	at_cmd
	RET

; at_cmd: send the AT line at HL, collect the answer for up to 1 s into the
; report (until "OK" or "ERROR").
at_cmd
	PUSH	HL
	LD	A,'>'
	CALL	rp_char
	POP	HL
	PUSH	HL
	CALL	rp_str
	POP	HL
.send
	LD	A,(HL)
	OR	A
	JR	Z,.sent
	PUSH	HL
	CALL	isa_open
.thre
	LD	A,(UART + 5)
	AND	0x20
	JR	Z,.thre
	POP	HL
	LD	A,(HL)
	LD	(UART),A
	CALL	isa_close
	INC	HL
	JR	.send
.sent
	LD	HL,1000
	CALL	dl_set
	XOR	A
	LD	(at_ok),A
.rx
	CALL	isa_open
	LD	A,(UART + 5)
	RRA
	JR	NC,.none
	LD	A,(UART)
	CALL	isa_close
	CP	10
	JR	Z,.rx
	CALL	rp_char
	CP	'K'			; "OK" (an ERROR waits for the 1 s end)
	JR	Z,.done
	JR	.rx
.none
	CALL	isa_close
	CALL	dl_due
	JR	NC,.rx
.done
	JP	rp_nl

isa_open
	DI
	IN	A,(0xE2)
	LD	(isa_e2),A
	LD	BC,0x1FFD
	LD	A,SH_1FFD | 0x10
	OUT	(C),A
	LD	A,0xD6			; ISA slot 1, I/O space
	LD	BC,0x00E2
	OUT	(C),A
	XOR	A
	LD	BC,0x9FBD
	OUT	(C),A
	RET
isa_close
	PUSH	AF
	LD	BC,0x9FBD
	LD	A,SH_9FBD
	OUT	(C),A
	LD	BC,0x1FFD
	LD	A,SH_1FFD
	OUT	(C),A
	LD	A,(isa_e2)
	LD	BC,0x00E2
	OUT	(C),A
	POP	AF
	EI
	RET
	ENDIF

; ----------------------------------------------------------------------
; Report: "UGTREP1",0 / status / text (CR LF lines, zero-terminated)
; ----------------------------------------------------------------------
rep_init
	LD	HL,UG_REPORT
	LD	DE,UG_REPORT + 1
	LD	BC,UG_REPORT_LEN - 1
	LD	(HL),0
	LDIR
	LD	HL,s_magic
	LD	DE,UG_REPORT
	LD	BC,8
	LDIR
	LD	A,'R'
	LD	(UG_REPORT + RP_STATUS),A
	LD	HL,UG_REPORT + RP_TEXT
	LD	(rp_ptr),HL
	RET
; rp_char: append A (kept).  Clobbers nothing else.
rp_char
	PUSH	HL
	PUSH	DE
	LD	HL,(rp_ptr)
	LD	DE,UG_REPORT + UG_REPORT_LEN - 2
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	JR	NC,.full
	LD	(HL),A
	INC	HL
	LD	(HL),0
	LD	(rp_ptr),HL
.full
	POP	DE
	POP	HL
	RET
rp_str
	LD	A,(HL)
	OR	A
	RET	Z
	CALL	rp_char
	INC	HL
	JR	rp_str
rp_nl
	LD	HL,s_crlf
	JR	rp_str
rp_hex16
	LD	A,H
	CALL	rp_hex8
	LD	A,L
rp_hex8
	PUSH	AF
	RRA
	RRA
	RRA
	RRA
	CALL	.nib
	POP	AF
.nib
	PUSH	AF
	AND	0x0F
	ADD	A,'0'
	CP	'9' + 1
	JR	C,.d
	ADD	A,7
.d
	CALL	rp_char
	POP	AF
	RET
; rp_dump: label HL, then B bytes from DE in hex, one line
rp_dump
	PUSH	DE
	PUSH	BC
	CALL	rp_str
	POP	BC
	POP	DE
.b
	LD	A,(DE)
	CALL	rp_hex8
	INC	DE
	DJNZ	.b
	JP	rp_nl

